SELECT * FROM ( SELECT b.id, b.bond_code, b.ecif_customer_no, b.customer_no, b.customer_name, b.biz_name, b.bond_type, b.biz_type, b.green_tech_flag, b.ext_rating, b.ext_rating_date, b.rating_agency, b.int_rating, b.int_rating_date, b.industry, b.customer_type, b.alert_customer, b.start_date, b.mature_date, b.currency, b.orig_amount, b.rmb_amount, b.balance, b.invest_rate, b.transfer_rate, b.guarantee_info, b.breach_flag, b.five_level_class, b.fund_used_flag, b.fund_used_up, b.installment_flag, b.installment_plan, b.our_bank_underwrite, b.lead_underwriter, b.manage_line, b.dept, b.agreed_usage, b.fund_account, b.fund_account_flag, b.supervise_account, b.supervise_account_flag, b.drawdown_check, b.is_original_am, b.exercise_flag, b.exercise_date, b.remark, b.js_remark, b.js_remark_flag, b.inspect_freq, b.inspector_post, b.creator, b.org_code, b.org_name, b.status, b.termination_reason, b.create_time, b.update_time, b.remark_number, b.is_passage, b.passage_amount, b.upper_storage_rate, CONCAT(w.user_name, '(', b.creator, ')') AS related_name, wb.dept_name, ROW_NUMBER() OVER (ORDER BY b.id DESC) AS rn FROM whjrscbmanage.bus_bond_business b LEFT JOIN whjrscbmanage.whfr_user w ON b.creator = w.user_id LEFT JOIN whjrscbmanage.whoa_branch_info wb ON b.org_code = wb.branch_no WHERE b.creator = 'admin' AND b.status != '5' AND b.status != '6' AND ('' = '' OR b.customer_name = '') AND ('' = '' OR b.biz_name LIKE CONCAT('%','','%')) AND ('' = '' OR b.status = '') ) t3 WHERE t3.rn > ('1' - 1) * '20' AND t3.rn <= '1' * '20'